package com.campusnova.model; import javax.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="college_information") public class CollegeInformation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private String infoKey; @Column(length=5000) private String infoValue; private boolean verified=false; private LocalDateTime updatedAt=LocalDateTime.now(); public CollegeInformation(){} public Long getId(){return id;} public String getInfoKey(){return infoKey;} public void setInfoKey(String v){infoKey=v;} public String getInfoValue(){return infoValue;} public void setInfoValue(String v){infoValue=v;} public boolean isVerified(){return verified;} public void setVerified(boolean v){verified=v;} }
